       [dict(lines=[(1, 'CREATE TABLE order_items ('), (1, '  item_id INTEGER PRIMARY KEY,'), (2, '  order_id INTEGER NOT NULL,'), (2, '  dish_id INTEGER NOT NULL,'), (3, '  quantity INTEGER NOT NULL CHECK (quantity >= 1),'),
                    (4, '  FOREIGN KEY (order_id) REFERENCES orders(order_id),'), (4, '  FOREIGN KEY (dish_id) REFERENCES dishes(dish_id)'), (4, ');')], run=4, he='הטבלה order_items נוצרה, עם שני מפתחות זרים.'),
        dict(lines=[(5, 'INSERT INTO order_items VALUES (1, 1201, 1, 1), (2, 1201, 2, 2);')], run=5, expect='n:2', he='שתי שורות נוספו.'),
        dict(lines=[(6, 'INSERT INTO order_items VALUES (3, 1201, 99, 1);')], run=6, expect='err:FOREIGN KEY constraint failed', he='נדחה: אין מנה 99.')],
       'שני מפתחות זרים בטבלה אחת. **המסד מוודא שכל שורה מצביעה על הזמנה קיימת ועל מנה קיימת.** בהמשך החלק נוסיף לה הערה, מחיר ששולם, והאם חזרה.',
